// Error Trigger 進來的資料：{ execution:{id,url,error{message},lastNodeExecuted,mode}, workflow:{id,name} }
const d = $input.first().json;
const wf = d.workflow || {};
const ex = d.execution || d.trigger || {};
const err = ex.error || {};

// 這些是「外部服務打嗝」型的錯誤，講白話讓人一眼知道不是自己系統壞掉
const raw = String(err.message || '未知錯誤');
let hint = '';
if (/50\d|522|ECONNABORTED|ETIMEDOUT|ECONNRESET|timeout/i.test(raw)) {
  hint = '\n💡 看起來是對方服務暫時打嗝，通常下一班會自己好';
} else if (/401|403|token|credential/i.test(raw)) {
  hint = '\n💡 可能是登入權杖過期，要人工處理';
}

const text = [
  '🚨 n8n 執行失敗',
  `📋 ${wf.name || wf.id || '未知流程'}`,
  ex.lastNodeExecuted ? `🔻 卡在：${ex.lastNodeExecuted}` : null,
  `💬 ${raw.slice(0, 300)}`,
  ex.url ? `🔗 ${ex.url}` : null,
].filter(Boolean).join('\n') + hint;

return [{ json: { userId: "Ufab42c56b2eb9b9a9ff18c367b85a6dd", text } }];
